<template><div v-if="auth.isLoggedIn" class="notif-wrap"><button class="notification" @click="open=!open">🔔<span v-if="unread" class="notif-count">{{unread>9?'9+':unread}}</span></button><div v-if="open" class="notif-pop"><div class="notif-head"><b>Notifications</b><button class="ghost" @click="markAll">Mark all read</button></div><div v-if="items.length"><div v-for="n in items" :key="n._id" class="notice" :class="{unread:!n.read}" @click="read(n)"><b>{{n.title}}</b><p>{{n.message}}</p><small>{{new Date(n.createdAt).toLocaleString()}}</small></div></div><div v-else class="empty">No notifications yet.</div></div></div></template>
<script setup lang="ts">import {onMounted,ref} from 'vue';import {useAuth} from '../stores/auth';import {api} from '../services/api';const auth=useAuth(),open=ref(false),items=ref<any[]>([]),unread=ref(0);async function load(){try{const d=await api.get('/me/notifications');items.value=d.data||[];unread.value=d.unread||0}catch{}}async function read(n:any){if(!n.read){await api.patch(`/me/notifications/${n._id}/read`,{});n.read=true;unread.value--}}async function markAll(){await api.patch('/me/notifications/read-all',{});items.value.forEach(n=>n.read=true);unread.value=0}onMounted(load)</script>
